insert into _fw_shared values ($fw${"pricing": {"goldSpotUsdPerOzt": 4178.2, "goldQuoteSource": "gold-api.com", "goldQuoteTimestamp": "2026-09-30T11:21:00Z", "lossFactor": 1.07, "markup": 2.0, "methodology": "Estimated grams (14K geometry, density-scaled for 10K/18K) x spot per gram x karat fineness x 1.07, plus category labor derived from the owner's 2027 enamel quotes; list price = 2 x cost rounded up to USD 10."}, "approval": {"blockers": ["Grams are geometry estimates; no sample has been cast or weighed.", "Labor per category is derived from the 2027 enamel quotes; the workshop has not quoted these 40 designs.", "Hero image is a design visualization (Higgsfield), one image per listing; photograph the physical piece before or after the first sale.", "Etsy taxonomy names for dangle and hoop earrings are not verified against the live tree; the push stops if they are missing."], "etsyDraftCreationAuthorized": true, "livePublicationAuthorized": false, "authority": "Owner instruction 2026-09-30: create listing-ready enamel proposals in the panel (listing onerileri), images included (\"Gorselleri de uret hepsini yurut\")."}, "variantSeal": "bfdad1da1f9f6c6a292f9211b3d5a945"}$fw$::jsonb, $fw$Each piece is made to order and ships free within the United States from New Jersey. Add a gift message at checkout and it ships with the piece.

Care: enamel is glass fused to gold. It keeps its colour, but it can chip on a hard knock, so take it off for the gym and the dishes and wipe it with a soft cloth.

The product image is a design visualization of the finished piece; the handmade piece may vary slightly.$fw$, $fw$Metal: solid 10K, 14K or 18K gold in yellow, white or rose.$fw$);

insert into public.products (
  id, org_id, sku, title, description, tags, materials, status, currency,
  price_cents, quantity, has_variations, image_url, num_images, product_type, listing_metadata
)
select f.pid, '2c254edf-2119-4079-b09e-dc672e32c1f9', f.sku, f.title,
  f.lead || E'\n\n' || f.story || E'\n\n' || s.metal || E'\nEnamel: ' || f.enamel || E'\nSize: ' || f.size || E'\n' || f.detail || E'\n\n' || s.tail,
  f.tags, ARRAY['Solid gold','Vitreous enamel']::text[], 'draft', 'USD',
  (select min(x) from unnest(f.price_k) x) * 1000, 20, true,
  'https://amuletta.artifactstudio.info/artifact/fw2627-enamel/' || f.mid || '.jpg', 1, f.ptype,
  s.meta || f.meta
from _fw f, _fw_shared s
where not exists (select 1 from public.products p where p.org_id = '2c254edf-2119-4079-b09e-dc672e32c1f9' and (p.sku = f.sku or p.id = f.pid));

insert into public.product_variants (
  org_id, sku, product_id, name, properties, price_cents, quantity, weight_grams, weight_source, active, currency
)
select '2c254edf-2119-4079-b09e-dc672e32c1f9',
  f.sku || '-' || k.k || c.cc || coalesce('-' || nullif(replace(replace(replace(z.s, 'US ', 'US'), ' inches', 'IN'), '.', '_'), ''), ''),
  p.id,
  f.name || ': ' || k.k || ' ' || c.cn || coalesce(', ' || z.s, ''),
  jsonb_build_object('Karat', k.k, 'Metal Color', c.cn) || case when f.axis3 <> '' then jsonb_build_object(f.axis3, z.s) else '{}'::jsonb end,
  f.price_k[(k.n - 1) * cardinality(f.sizes) + z.n] * 1000, 20,
  f.grams[(k.n - 1) * cardinality(f.sizes) + z.n], 'geometry_estimate', true, 'USD'
from _fw f
join public.products p on p.org_id = '2c254edf-2119-4079-b09e-dc672e32c1f9' and p.sku = f.sku and p.etsy_listing_id is null
cross join unnest(ARRAY['10K','14K','18K']) with ordinality k(k, n)
cross join (values ('Y','Yellow Gold'),('W','White Gold'),('R','Rose Gold')) c(cc, cn)
cross join unnest(f.sizes) with ordinality z(s, n)
on conflict (org_id, sku) do update set
  product_id = excluded.product_id, name = excluded.name, properties = excluded.properties,
  price_cents = excluded.price_cents, quantity = excluded.quantity, weight_grams = excluded.weight_grams,
  weight_source = excluded.weight_source, active = excluded.active, updated_at = now();

insert into public.listing_images (org_id, product_id, url, source, alt, position)
select p.org_id, p.id, p.image_url, 'url', f.title, 0
from _fw f
join public.products p on p.org_id = '2c254edf-2119-4079-b09e-dc672e32c1f9' and p.sku = f.sku and p.etsy_listing_id is null
where not exists (select 1 from public.listing_images li where li.product_id = p.id and li.url = p.image_url);

commit;
